require_once __DIR__.'/../includes/auth.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['error'=>'Method not allowed'],405);verify_api_csrf();$in=json_decode(file_get_contents('php://input'),true)??[];$cid=filter_var($in['conversation_id']??null,FILTER_VALIDATE_INT);if(!$cid||!is_member($pdo,$cid,current_user_id()))json_response(['error'=>'Not allowed'],403);if(!empty($in['typing']))$pdo->prepare('INSERT INTO typing_status(conversation_id,user_id,updated_at) VALUES(?,?,NOW()) ON DUPLICATE KEY UPDATE updated_at=NOW()')->execute([$cid,current_user_id()]);else $pdo->prepare('DELETE FROM typing_status WHERE conversation_id=? AND user_id=?')->execute([$cid,current_user_id()]);json_response(['ok'=>true]);
